// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    Receiver r;

    function setUp() public { 
        c = new airPort();
        r = new Receiver();
    }

    // fuzzed params: from address (as uint160), single recipient flag encoded as an index length
    // We let the fuzzer pick a uint256 lenIndicator and an addressFrom indicator so it can find len==1 case
    function testFuzz_property(uint256 lenIndicator, uint256 fromAddrSeed, uint256 v) public {
        // keep v wide but bounded to a reasonable range
        v = bound(v, 0, type(uint256).max);

        // construct a _tos array whose length is either 1 or >=2 depending on lenIndicator
        // We want to ensure the fuzzer can hit the single-element case that distinguishes mutant
        uint256 len = (lenIndicator % 3) + 1; // yields lengths 1,2,3

        address from = address(uint160(fromAddrSeed));

        // build recipients array of length `len`, all pointing to our Receiver helper so we can observe calls
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = address(r);
        }

        // The Receiver has a function transferFrom(address,address,uint256) that always returns true
        // and records the calls. We do not make it revert here; the distinguishing behavior is the require on length.

        // call and observe whether it reverts
        bool ok;
        try c.transfer(from, address(r), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for ANY inputs with _tos.length >= 1, the reference implementation does NOT revert and thus ok==true.
        // The mutant that changes require(_tos.length > 0) to >1 will cause ok==false when len==1.

        // So we assert that when length >= 1 the call does NOT revert (ok == true).
        // This will hold for the reference and be violated by the mutant for some fuzzed inputs (len==1).
        assertTrue(ok);
    }
}

// observing counterparty: records calls made by C via the transferFrom selector
contract Receiver {
    event Called(address from, address to, uint256 v);

    // match selector: transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        emit Called(from, to, value);
        return true;
    }
}
